"""Context review of the eab06baf logs for the categories that need judgement; classes and counts only.

Usage: eab_context.py LOG_ROOT REVIEW_SETS_JSON
"""
import json
import re
import subprocess
import sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, "~/leveraged-etf-risk-analytics/.claude/hooks")
import transcript_privacy as tp  # noqa: E402

sys.path.insert(0, str(Path(__file__).parent))
from context_review import records, strings, tool_pairs  # noqa: E402

REPO = "~/leveraged-etf-risk-analytics"
ROOT = Path(sys.argv[1])
SETS = json.load(open(sys.argv[2]))
HOME = Path.home()
MEMDIR = HOME / ".claude/projects/-Users-[REDACTED:user]-leveraged-etf-risk-analytics/memory"
LOGNAME = r"\d{4}-\d{2}-\d{2}_\d{4}_[0-9a-f]{8}-\d+"
LIST = re.compile(r"docker (?:compose[^|;&]* )?(?:ps|stats)\b")
APP = re.compile(r"/Applications/([^/\n\"\\]+?)\.app|([A-Za-z][\w .-]*?)\.app/Contents")
HOME_ROOT = re.compile(r"(?<![\w/])~/([^/\s'\"`)\]\\,;:|]+)")
ENV = re.compile(r"^([A-Z_][A-Z0-9_]{2,})=(.*)$")
KNOWN_APPS = {"Python": "Python framework bundle", "Visual Studio Code": "VS Code (project editor)", "Code Helper": "VS Code helper process",
              "Code": "VS Code", "Docker": "Docker (project tool)"}
log = subprocess.run(["git", "-C", REPO, "log", "--all", "--format=%B"], capture_output=True, text=True).stdout


def committed(v):
    return subprocess.run(["git", "-C", REPO, "grep", "-q", "-F", "-e", v, "origin/main", "--", ":!docs/ai-usage"]).returncode == 0


mem = {}
for f in MEMDIR.glob("*.md"):
    t = f.read_text()
    for line in (t.split("---", 2)[-1] if t.startswith("---") else t).splitlines():
        line = line.strip().lstrip("-*").strip()
        if len(line) >= 30 and re.search(r"[A-Za-z]{4}", line):
            mem.setdefault(line, f.name)

out = {k: Counter() for k in ("memory in ordinary tool calls", "containers", "apps", "e-mail", "home roots", "exclude", "env dumps")}
for d in sorted(p for p in ROOT.iterdir() if p.is_dir()):
    recs = records(d)
    for name, inp, res in tool_pairs(recs):
        blob = json.dumps(inp)
        is_mem = ".claude/projects" in blob and "/memory" in blob
        if not is_mem:
            for line in mem:
                if line in "\n".join(strings(inp)):
                    out["memory in ordinary tool calls"][f"{name}: {'in a commit message pushed to GitHub' if line in log else 'NOT in any commit message'}"] += 1
        cmd = str(inp.get("command", ""))
        if LIST.search(cmd):
            for tok in set(re.findall(r"(?<![\w.-])([a-z0-9][a-z0-9_.-]*[a-z][a-z0-9_.-]*[-_]\d+)(?![\w.-])", res)):
                if tok.startswith(("etf-risk-jobs", "docker")):
                    continue
                kind = ("AI-log folder name" if re.fullmatch(LOGNAME, tok) else "BuildKit stage" if re.fullmatch(r"stage-\d+", tok)
                        else "Kafka client id" if re.fullmatch(r"(producer|consumer|adminclient)-\d+", tok)
                        else "scratchpad claude-<uid>" if re.fullmatch(r"claude-\d+", tok)
                        else "reviewed other-project name" if tok in SETS["container_names"] + SETS["generic_prefix_docker_tokens"]
                        else "in committed files" if committed(tok) else "NEW, unexplained")
                out["containers"][kind] += 1
        if ".git/info/exclude" in cmd:
            reads = bool(re.search(r"(cat|head|tail|sed -n|less)\s[^|;]*\.git/info/exclude", cmd))
            out["exclude"][f"{name}: {'reads the file' if reads else 'mentions the path only'}"] += 1
        run = []
        for line in res.splitlines() + [""]:
            m = ENV.match(line)
            if m:
                run.append(m)
                continue
            if len(run) >= 5:
                keys = [x.group(1) for x in run]
                secretish = sum(1 for x in run if re.search(r"KEY|SECRET|TOKEN|PASSWORD", x.group(1)) and x.group(2) and not committed(x.group(2)))
                out["env dumps"][f"{len(keys)} variables, project ETF_RISK_* {sum(k.startswith('ETF_RISK') for k in keys)}, secret-like with an uncommitted value {secretish}"] += 1
            run = []
    for r in recs:
        for s in strings(r):
            for a, b in APP.findall(s):
                n = (a or b).strip()
                out["apps"][KNOWN_APPS.get(n, f"UNKNOWN app ({len(n)} chars)")] += 1
            for m in tp.EMAIL.finditer(s):
                addr = m.group(0)
                if addr.lower() in tp.EMAIL_ALLOWLIST:
                    continue
                out["e-mail"]["pytest decorator after an escaped newline" if addr.split("@")[1].startswith("pytest.") and s[m.start() - 1] == "\\"
                              else "in committed code or tests" if committed(addr) else "OTHER address"] += 1
            for root in HOME_ROOT.findall(s):
                if root.startswith(("leveraged-etf-risk-analytics", "etf-risk-", ".")):
                    continue
                p = HOME / root
                kind = ("Library" if root == "Library" else "the tests' ~/proj" if root == "proj"
                        else "project helper script" if p.is_file() and "leveraged-etf-risk-analytics" in p.read_text(errors="replace")
                        else "a git repository (another project)" if (p / ".git").exists() else "UNKNOWN root")
                out["home roots"][kind] += 1
for k, c in out.items():
    print(f"== {k}: " + ("; ".join(f"{n} x {v}" for v, n in sorted(c.items())) or "none"))

