"""Stage sanitized copies of one session's AI-log folders: memory content and other projects' container names.

Usage: sanitize_eab.py HOOK_DIR REVIEW_SETS_JSON SRC_ROOT DEST_ROOT
Successor of sanitize_published_v1_pr24.py, for session eab06baf:
- a memory call is a file tool whose target is in the memory folder, or a Bash command that refers to it;
- memory lines already public (committed files or commit messages on GitHub) are not redacted;
- line-level memory redaction also covers inputs of ordinary tool calls and compaction summaries;
- memory text in a typed prompt is never exempted automatically: the run stops for review;
- every folder is written to DEST_ROOT (unchanged ones byte for byte).
Reads and writes byte-exactly; transcript.md is re-rendered with the hook's render_markdown. Prints counts only.
"""
import json
import re
import subprocess
import sys
import tempfile
from collections import Counter
from datetime import datetime
from pathlib import Path

sys.path.insert(0, sys.argv[1])
from save_transcript import render_markdown  # noqa: E402

REPO = Path("~/leveraged-etf-risk-analytics")
MEMORY_DIR = Path.home() / ".claude/projects/-Users-[REDACTED:user]-leveraged-etf-risk-analytics/memory"
SETS = json.load(open(sys.argv[2]))
SRC, DEST = Path(sys.argv[3]), Path(sys.argv[4])
MEM, CON = "[REDACTED:memory]", "[REDACTED:container]"
[REDACTED:memory]
KEEP_KEYS = {"file_path", "filePath", "path", "notebook_path", "type", "id", "tool_use_id", "name", "uuid", "parentUuid",
             "timestamp", "sessionId"}
MEMSLUG = re.compile(r"\.claude/projects/[^\s\"'/]*/memory\b")
SECTION = re.compile(r"(Contents of [^\n]*?/memory/[^\n]*?:)(\s+)(.*?)(\s*)(?=\n\s*Contents of |</system-reminder>|\Z)", re.S)
[REDACTED:memory]


def memory_lines():
    lines = set()
    for f in MEMORY_DIR.glob("*.md"):
        t = f.read_text(encoding="utf-8")
        for line in (t.split("---", 2)[-1] if t.startswith("---") else t).splitlines():
            line = line.strip().lstrip("-*").strip()
            if len(line) >= 30 and re.search(r"[A-Za-z]{4}", line):
                lines.add(line)
    with tempfile.NamedTemporaryFile("w", delete=False) as fh:
        fh.write("\n".join(sorted(lines)))
    in_files = set(subprocess.run(["git", "-C", str(REPO), "grep", "-h", "-o", "-F", "-f", fh.name, "origin/main", "--", ":!docs/ai-usage"],
                                  capture_output=True, text=True).stdout.splitlines())
    Path(fh.name).unlink()
    messages = subprocess.run(["git", "-C", str(REPO), "log", "--remotes", "--format=%B"], capture_output=True, text=True).stdout
    public = in_files | {line for line in lines if line in messages}
    return lines - public, len(lines), len(public)


MEMORY, MEMORY_ALL, MEMORY_PUBLIC = memory_lines()
NAMES = sorted(set(SETS["container_names"]) | set(SETS["generic_prefix_docker_tokens"]), key=len, reverse=True)
CONTAINER = re.compile(
    "|".join([r"(?<![A-Za-z0-9])" + re.escape(n) + r"(?![A-Za-z0-9])" for n in NAMES]
             + [r"(?<![A-Za-z0-9])" + re.escape(p) + r"(?:[-_][A-Za-z0-9][A-Za-z0-9_.-]*)?(?![A-Za-z0-9])" for p in SETS["distinct_prefixes"]]))


def has_memory(s):
    s = SANITIZED_HEADER.sub("", s)
    return HEADER in s or any(line in s for line in MEMORY)


def is_memory_call(name, inp):
    if name == "Bash":
        return bool(MEMSLUG.search(str(inp.get("command", ""))))
    return any(MEMSLUG.search(str(inp.get(k, ""))) for k in ("file_path", "path", "notebook_path"))


def is_typed_prompt(r):
    return r.get("type") == "user" and (r.get("origin") or {}).get("kind") == "human" and not r.get("isCompactSummary")


class Sanitizer:
    def __init__(self):
        self.counts = Counter()

    def wipe(self, obj, key=None):
        if isinstance(obj, str):
            if key in KEEP_KEYS or obj == MEM:
                return obj
            self.counts["memory"] += 1
            return MEM
        if isinstance(obj, list):
            return [self.wipe(v, key) for v in obj]
        if isinstance(obj, dict):
            return {k: self.wipe(v, k) for k, v in obj.items()}
        return obj

    def scrub(self, obj, key=None):
        if isinstance(obj, str):
            if key in KEEP_KEYS:
                return obj
            n = 0

            def section(m):
                nonlocal n
                if not m.group(3) or m.group(3).startswith(MEM):
                    return m.group(0)
                n += 1
                return m.group(1) + m.group(2) + MEM + m.group(4)
            obj = SECTION.sub(section, obj)
            if n:
                self.counts["memory"] += n
            if has_memory(obj):
                self.counts["memory"] += 1
                return MEM
            return obj
        if isinstance(obj, list):
            return [self.scrub(v, key) for v in obj]
        if isinstance(obj, dict):
            return {k: self.scrub(v, k) for k, v in obj.items()}
        return obj

    def lines(self, obj, key=None):
        if isinstance(obj, str):
            if key in KEEP_KEYS or not has_memory(obj):
                return obj
            out = []
            for line in obj.split("\n"):
                if has_memory(line):
                    self.counts["memory"] += 1
                    out.append(MEM)
                else:
                    out.append(line)
            return "\n".join(out)
        if isinstance(obj, list):
            return [self.lines(v, key) for v in obj]
        if isinstance(obj, dict):
            return {k: self.lines(v, k) for k, v in obj.items()}
        return obj

    def containers(self, obj, key=None):
        if isinstance(obj, str):
            if key in ("type", "id", "tool_use_id", "uuid", "parentUuid", "timestamp", "sessionId"):
                return obj
            new, n = CONTAINER.subn(CON, obj)
            if n:
                self.counts["container"] += n
            return new
        if isinstance(obj, list):
            return [self.containers(v, key) for v in obj]
        if isinstance(obj, dict):
            return {k: self.containers(v, k) for k, v in obj.items()}
        return obj

    def record(self, rec, memory_ids):
        t = rec.get("type")
        if t not in ("user", "assistant"):
            return self.containers(self.scrub(rec))  # attachments, API-request, prompt copies and other records
        rec = dict(rec)
        msg = rec.get("message")
        if rec.get("isCompactSummary") and isinstance(msg, dict):
            rec["message"] = {**msg, "content": self.lines(msg.get("content"))}
        elif is_typed_prompt(rec):
            texts = msg.get("content") if isinstance(msg.get("content"), str) else " ".join(
                b.get("text", "") for b in msg.get("content") or [] if isinstance(b, dict) and b.get("type") == "text")
            if any(line in texts for line in MEMORY):
                raise SystemExit("STOP: memory text in a typed prompt needs a privacy review before it can be kept or redacted")
        if isinstance(msg, dict) and isinstance(msg.get("content"), list):
            blocks = []
            for b in msg["content"]:
                if isinstance(b, dict) and b.get("type") == "tool_use":
                    inp = b.get("input") or {}
                    if b.get("id") in memory_ids:
                        b = {**b, "input": {k: (v if k in KEEP_KEYS else self.wipe(v, k)) for k, v in inp.items()}}
                    else:
                        b = {**b, "input": self.lines(inp)}
                elif isinstance(b, dict) and b.get("type") == "tool_result" and b.get("tool_use_id") in memory_ids:
                    b = {**b, "content": self.wipe(b.get("content"))}
                elif isinstance(b, dict) and b.get("type") == "tool_result":
                    b = {**b, "content": self.lines(b.get("content"))}
                elif isinstance(b, dict) and b.get("type") == "text" and "<system-reminder>" in b.get("text", ""):
                    b = self.scrub(b)
                blocks.append(b)
            rec["message"] = {**msg, "content": blocks}
            used = {b.get("tool_use_id") for b in msg["content"] if isinstance(b, dict)}
            for k in [k for k in rec if k not in ("message", *KEEP_KEYS)]:
                rec[k] = self.wipe(rec[k], k) if (k == "toolUseResult" and used & memory_ids) else self.lines(rec[k], k)
        elif isinstance(msg, dict) and isinstance(msg.get("content"), str) and ("<system-reminder>" in msg["content"] or rec.get("isMeta")):
            rec["message"] = {**msg, "content": self.scrub(msg["content"])}
        return self.containers(rec)


def header(md):
    session = re.search(r"Session: `([^`]+)`", md).group(1)
    sent = datetime.strptime(re.search(r"prompt sent (\d{4}-\d{2}-\d{2} \d{2}:\d{2})", md).group(1), "%Y-%m-%d %H:%M")
    number = int(re.search(r"^# Claude Code message (\d+)", md, re.M).group(1))
    m = re.search(r"Redactions \(.*?\): (.*?)\. Rules:", md)
    counts = Counter()
    if m and m.group(1) != "none":
        for part in m.group(1).split(", "):
            k, v = part.rsplit(" ×", 1)
            counts[k] = int(v)
    return session, number, sent, counts


def main():
    total = Counter()
    print(f"memory reference lines: {MEMORY_ALL}; public (committed files or commit messages), not redacted: {MEMORY_PUBLIC}")
    for src in sorted(p for p in SRC.iterdir() if p.is_dir()):
        dest = DEST / src.name
        jsonl = (src / "transcript.jsonl").read_bytes().decode("utf-8")
        md = (src / "transcript.md").read_bytes().decode("utf-8")
        session, number, sent, counts = header(md)
        assert render_markdown(jsonl, session, number, sent, counts) == md, f"{src.name}: transcript.md does not re-render"
        lines = jsonl.split("\n")
        recs = [json.loads(l) if l.strip() else None for l in lines]
        ids = set()
        for r in recs:
            msg = (r or {}).get("message") if isinstance((r or {}).get("message"), dict) else {}
            for b in msg.get("content") if isinstance(msg.get("content"), list) else []:
                if isinstance(b, dict) and b.get("type") == "tool_use" and is_memory_call(b.get("name"), b.get("input") or {}):
                    ids.add(b.get("id"))
        s = Sanitizer()
        out = []
        for line, r in zip(lines, recs):
            if r is None:
                out.append(line)
                continue
            new = s.record(r, ids)
            out.append(line if new == r else json.dumps(new, ensure_ascii=False))
        new_jsonl = "\n".join(out)
        dest.mkdir(parents=True, exist_ok=True)
        if new_jsonl == jsonl:
            (dest / "transcript.jsonl").write_bytes(jsonl.encode("utf-8"))
            (dest / "transcript.md").write_bytes(md.encode("utf-8"))
            total["folders unchanged"] += 1
            continue
        assert s.counts, f"{src.name}: records changed without a counted redaction"
        counts.update(s.counts)
        (dest / "transcript.jsonl").write_bytes(new_jsonl.encode("utf-8"))
        (dest / "transcript.md").write_bytes(render_markdown(new_jsonl, session, number, sent, counts).encode("utf-8"))
        total["folders sanitized"] += 1
        total["memory calls"] += len(ids)
        total.update(s.counts)
        print(f"{src.name}: " + ", ".join(f"{k} {v}" for k, v in sorted(s.counts.items())) + f" (memory calls {len(ids)})")
    print(dict(total))


if __name__ == "__main__":
    main()

